export const BODY: string = "\n<p>GIF ساکت تصاویر کی سیریز سے بنی مختصر لوپنگ اینیمیشن ہے۔ یہ بغیر آواز کے چلتی ہے، ہمیشہ یا مقرر لوپ تعداد تک دہراتی ہے، اور تقریباً ہر جگہ کام کرتی ہے۔</p>\n<p>GIF میکر آپ کی تصاویر کو براؤزر میں متحرک GIF میں بدلتا ہے۔ دو یا اس سے زیادہ فریم تصاویر اپ لوڈ کریں، ہر فریم کے لیے وقت سیٹ کریں، لوپ تعداد چنیں، اور فائل بنائیں۔</p>\n<p>یہ گائیڈ بتاتی ہے کہ GIF کیسے کام کرتے ہیں، فریم کیسے چنیں اور وقت کیسے دیں، اور فائل سائز کو شیئر کرنے کے لیے کافی چھوٹا کیسے رکھیں۔ چاہے آپ ری ایکشن GIF بنائیں، پروڈکٹ ڈیمو، یا ٹیوٹوریل قدم۔</p>\n<h2 id=\"what-is-a-gif\">GIF کیا ہے؟</h2>\n<p>GIF کا مطلب Graphics Interchange Format ہے، اور یہ 1980 کی دہائی کے آخر سے ہے۔ یہ روزمرہ استعمال میں سب سے پرانے تصویر فارمیٹ میں سے ایک ہے، اور اس کی سادگی ہی اس کی طاقت ہے۔</p>\n<p>GIF فریموں کی سیریز محفوظ کرتا ہے، ہر ایک مختصر وقت کے لیے ایک کے بعد ایک دکھایا جاتا ہے۔ پلیئر فریموں سے لوپ کرتا ہے، اور نتیجہ مختصر ویڈیو کلپ کی طرح لگتا ہے۔</p>\n<p>GIF فی فریم 256 رنگوں تک محدود ہیں، اسی لیے وہ مثالوں، اسکرین شاٹس، اور سادہ اینیمیشن کے لیے مکمل رنگ تصاویر سے بہتر موزوں ہیں۔ تصویر GIF پوسٹر جیسی ہو سکتی ہے۔</p>\n<p>فارمیٹ عالمگیر ہے۔ چیٹ ایپس، سوشل فیڈ، فورم، ای میل، اور ویب سائٹس سب GIF کو بغیر کسی خاص پلیئر کے دکھاتی ہیں۔ یہ عالمگیریت ہی وجہ ہے کہ GIF ابھی بھی ہر جگہ ہے۔</p>\n<h2 id=\"how-the-gif-maker-works\">GIF میکر کیسے کام کرتا ہے</h2>\n<p>GIF میکر آپ کی تصاویر کو مکمل طور پر آپ کے براؤزر میں متحرک GIF میں انکوڈ کرتا ہے۔ آپ کے فریم کبھی آپ کے آلے کو نہیں چھوڑتے، جو اہمیت رکھتا ہے جب تصاویر غیر جاری شدہ ہوں۔</p>\n<p>آپ دو یا اس سے زیادہ فریم تصاویر اپ لوڈ کرتے ہیں، اور ٹول انہیں ترتیب سے لگاتا ہے۔ آپ فریموں کو گھسیٹ کر دوبارہ ترتیب دے سکتے ہیں، فریم کو نقل کر کے اسے زیادہ دیر رکھ سکتے ہیں، اور فریم ہٹا سکتے ہیں۔</p>\n<p>ہر فریم کو اپنی تاخیر ملتی ہے، سیکنڈ کے حصوں میں ناپی جاتی ہے۔ مختصر تاخیر اینیمیشن کو تیز بناتی ہے، اور لمبی تاخیر اسے سست بناتی ہے۔ آپ تمام فریموں کے لیے واحد تاخیر بھی سیٹ کر سکتے ہیں۔</p>\n<p>Live Timing Preview اینیمیشن کو آپ کی موجودہ سیٹنگ سے بنانے سے پہلے چلتے ہوئے دکھاتا ہے۔ جو آپ پیش نظارہ میں دیکھتے ہیں وہی تیار GIF ہے۔</p>\n<h2 id=\"choosing-frames\">فریم چننا</h2>\n<p>فریم وہ ساکت تصاویر ہیں جو اینیمیشن بناتی ہیں، اور فریموں کا انتخاب طے کرتا ہے کہ GIF کام کرتی ہے یا نہیں۔ اچھی GIF چھوٹی کہانی سناتی ہے: پہلے اور بعد، قدم بہ قدم، یا تعمیر اور ادائیگی۔</p>\n<p>ایک جیسے سائز اور شکل والے فریم استعمال کریں۔ ٹول مختلف تناسب والی تصاویر سنبھالتا ہے، مگر میل کھانے والے ابعاد والا فریم سیٹ ہموار اینیمیشن دیتا ہے۔</p>\n<p>فریم تعداد معتدل رکھیں۔ پانچ سے پندرہ فریم والی GIF عام طور پر ری ایکشن، ڈیمو، یا مختصر ٹیوٹوریل قدم کے لیے کافی ہوتی ہے۔ زیادہ فریم کا مطلب لمبی اینیمیشن اور بڑی فائل ہے۔</p>\n<p>ترتیب تعداد سے زیادہ اہمیت رکھتی ہے۔ پروڈکٹ گھماؤ گھڑی کی سمت یا الٹا پڑھتا ہے، ٹیوٹوریل قدم ترتیب سے پڑھتا ہے، اور ری ایکشن تعمیر اور ادائیگی کے طور پر پڑھتا ہے۔</p>\n<h2 id=\"frame-delays-and-timing\">فریم تاخیر اور وقت</h2>\n<p>فریم تاخیر یہ ہے کہ ہر فریم اسکرین پر کتنی دیر رہتا ہے، اور یہ بنیادی کنٹرول ہے کہ اینیمیشن کیسا محسوس ہوتا ہے۔ فی فریم 0.1 سیکنڈ کی تاخیر تیز، توانائی والی حرکت دیتی ہے۔</p>\n<p>اینیمیشن کے جسم کے لیے مستقل تاخیر اور زور چاہنے والے فریموں کے لیے لمبی تاخیر استعمال کریں۔ شروع میں عنوان سلائیڈ لمبی رکاوٹ کی حقدار ہے تاکہ اسے پڑھا جا سکے۔</p>\n<p>1، 2، 5، اور 10 فریم فی سیکنڈ کے فوری پری سیٹ آپ کو نقطہ آغاز دیتے ہیں۔ ایک فریم فی سیکنڈ سست سلائیڈ شو ہے، پانچ فریم فی سیکنڈ تیز ڈیمو ہے۔</p>\n<p>وقت کو Live Timing Preview میں ٹیسٹ کریں۔ نمبر کے طور پر درست لگنے والی تاخیر حرکت میں غلط محسوس ہو سکتی ہے، اور پیش نظارہ اصل احساس دکھاتا ہے۔ اگر اینیمیشن جلدی لگے تو تاخیر بڑھائیں۔</p>\n<h2 id=\"frame-rate-presets\">فریم شرح پری سیٹ</h2>\n<p>پری سیٹ فریم فی سیکنڈ کو تاخیر میں ترجمہ کرتے ہیں۔ ایک FPS کا مطلب ہر فریم ایک سیکنڈ دکھاتا ہے، جو ساکت تصاویر کے سلائیڈ شو کے لیے موزوں ہے جہاں ہر تصویر مکمل دیکھنے کی حقدار ہے۔</p>\n<p>پانچ FPS کا مطلب فی فریم سیکنڈ کا پانچواں حصہ ہے، جو زیادہ تر GIF کے لیے بہترین جگہ ہے۔ یہ حرکت محسوس کرنے کے لیے کافی تیز ہے اور اتنی سست ہے کہ ہر فریم رجسٹر ہو۔</p>\n<p>دس FPS کا مطلب فی فریم سیکنڈ کا دسواں حصہ ہے، جو ٹول کی پیش کردہ ہموار ترین ہے۔ یہ اس حرکت کے لیے موزوں ہے جو سیال لگنی چاہیے، جیسے گھماؤ یا چلنے کا چکر۔</p>\n<p>زیادہ ہمیشہ بہتر نہیں ہوتا۔ تیس فریم والی دس فریم فی سیکنڈ GIF تین سیکنڈ لمبی اور بھاری ہوتی ہے، جبکہ پانچ فریم فی سیکنڈ پر وہی خیال ہلکا اور تقریباً اتنا ہی موثر ہوتا ہے۔</p>\n<h2 id=\"loop-options\">لوپ آپشن</h2>\n<p>لوپنگ طے کرتی ہے کہ GIF کتنی بار چلتی ہے۔ لامحدود لوپ ہمیشہ چلتا ہے، جو کلاسک GIF رویہ ہے اور ری ایکشن، سجاوٹ، اور پس منظر اینیمیشن کے لیے درست انتخاب ہے۔</p>\n<p>محدود لوپ مقرر بار چلتا ہے اور پھر حتمی فریم پر رکتا ہے۔ یہ ٹیوٹوریل یا ڈیمو کے لیے موزوں ہے جہاں دیکھنے والے کو تیار حالت پر ختم ہونا چاہیے۔</p>\n<p>واحد کھیل، یا ایک لوپ تعداد، اینیمیشن کو ایک بار دکھاتا ہے اور رکتا ہے۔ یہ اس پیغام کے لیے موزوں ہے جہاں اینیمیشن ایک بار کا انکشاف ہے، جیسے پہلے اور بعد۔</p>\n<p>لوپ کو سیاق کے لیے چنیں۔ چیٹ ری ایکشن لامحدود لوپ چاہتا ہے، پروڈکٹ ڈیمو چند لوپ چاہتا ہے، اور ٹیوٹوریل قدم نتیجے پر ختم ہونا چاہتا ہے۔</p>\n<h2 id=\"frame-fit-contain-vs-cover\">فریم فٹ: Contain بمقابلہ Cover</h2>\n<p>Frame Fit طے کرتا ہے کہ جب فریموں کے تناسب مختلف ہوں تو کیا ہوتا ہے۔ Contain ہر فریم کو بغیر کراپ کے آؤٹ پٹ سائز کے اندر فٹ کرتا ہے، اس لیے پورا فریم نظر آتا ہے۔</p>\n<p>Cover فریم کو کراپ کر کے آؤٹ پٹ سائز کو مکمل بھرتا ہے، اس لیے کوئی خالی بینڈ نہیں ہوتا مگر فریم کے کنارے کٹ سکتے ہیں۔ یہ صاف، مکمل بھرے ہوئے نظر دیتا ہے۔</p>\n<p>Contain چنیں جب ہر فریم کا ہر حصہ اہمیت رکھتا ہے، جیسے ٹیوٹوریل جہاں کراپ شدہ بٹن قدم چھپا دے گا۔ Cover چنیں جب اینیمیشن کو فریم کو صاف بھرنا ہو۔</p>\n<p>جب آپ آؤٹ پٹ چوڑائی ایڈٹ کریں تو تناسب مقرر رہتا ہے، اس لیے چوڑائی بدلنا پوری GIF کو کھینچنے کے بجائے سکیل کرتا ہے۔ آؤٹ پٹ ابعاد ایک بار سیٹ کریں۔</p>\n<h2 id=\"output-size-and-dimensions\">آؤٹ پٹ سائز اور ابعاد</h2>\n<p>آؤٹ پٹ چوڑائی تیار GIF کی پکسل چوڑائی سیٹ کرتی ہے، اور اونچائی فریموں کے تناسب سے آتی ہے۔ 480 پکسل چوڑائی عام انتخاب ہے۔</p>\n<p>GIF کے لیے چھوٹا عام طور پر بہتر ہوتا ہے۔ 480 پکسل چوڑی GIF تیزی سے شیئر کرنے کے لیے کافی چھوٹی اور فون پر صاف دیکھنے کے لیے کافی بڑی ہوتی ہے۔ 1000 پکسل چوڑی GIF چار گنا پکسل رکھتی ہے۔</p>\n<p>ٹول آؤٹ پٹ ابعاد کے لیے کم سے کم اور زیادہ سے زیادہ سیٹ کرتا ہے، اس لیے انتہائی سائز ممکن نہیں۔ بہت چھوٹے آؤٹ پٹ تفصیل کھو دیتے ہیں، اور بہت بڑے آؤٹ پٹ بہت بڑی فائلیں بناتے ہیں۔</p>\n<p>ابعاد کو منزل کے خلاف چیک کریں۔ چیٹ ایپ بڑی GIF کو ویسے بھی نیچے سکیل کر سکتی ہے، اس لیے بڑی فائل بھیجنا بغیر نظر آنے والے فائدے کے بینڈوڈتھ ضائع کرتا ہے۔ ویب سائٹ کو زیادہ چاہیے ہو سکتا ہے۔</p>\n<h2 id=\"color-palette-quality\">رنگ پیلیٹ کوالٹی</h2>\n<p>GIF فی فریم زیادہ سے زیادہ 256 رنگ محفوظ کرتے ہیں، اس لیے انکوڈر کو چننا ہوتا ہے کہ کون سے رنگ رکھیں۔ Color Palette Quality سلائیڈر کنٹرول کرتا ہے کہ وہ انتخاب کتنی احتیاط سے کیا جائے۔</p>\n<p>زیادہ کوالٹی ہموار گریڈینٹ اور زیادہ درست جلد کے رنگ دیتی ہے، مگر انکوڈ کرنے میں زیادہ وقت لیتی ہے اور تھوڑی بڑی فائل بنا سکتی ہے۔ کم کوالٹی تیزی سے انکوڈ کرتی ہے۔</p>\n<p>تصاویر کے لیے زیادہ پیلیٹ کوالٹی استعمال کریں۔ تصاویر میں ہزاروں رنگ ہوتے ہیں، اور محتاط پیلیٹ تصویر کو پہچاننے کے قابل رکھتی ہے۔ مثالوں اور اسکرین شاٹ کے لیے کم کوالٹی ٹھیک ہے۔</p>\n<p>پیلیٹ کو گریڈینٹ یا چہرے والے فریم پر ٹیسٹ کریں۔ وہ جگہیں ہیں جہاں خراب پیلیٹ سب سے پہلے ظاہر ہوتی ہے، آسمان میں بینڈنگ یا جلد میں دھبوں کے طور پر۔ اگر یہ ظاہر ہو تو کوالٹی بڑھائیں۔</p>\n<h2 id=\"large-gif-warning\">بڑی GIF وارننگ</h2>\n<p>ٹول Large GIF Warning دکھاتا ہے جب تخمینہ شدہ فائل 5 MB یا 15 MB سے گزرے۔ وہ حدیں اس لیے ہیں کیونکہ بڑی GIF شیئر کرنا مشکل ہوتا ہے: وہ آہستہ لوڈ ہوتی ہیں اور موبائل ڈیٹا کھاتی ہیں۔</p>\n<p>GIF تین وجوہات سے بڑی ہوتی ہے: بہت سے فریم، بڑے ابعاد، یا زیادہ فریم شرح۔ ان تینوں میں سے کسی ایک کو کاٹنا فائل سکڑتا ہے۔ کم فریم عام طور پر آسان ترین کٹوتی ہے۔</p>\n<p>جب وارننگ ظاہر ہو تو پہلے آؤٹ پٹ چوڑائی کم کریں۔ چوڑائی آدھا کرنا پکسل تعداد کو چوتھائی کرتا ہے، جو دستیاب سب سے بڑی واحد بچت ہے۔ پھر نقل فریم کاٹیں۔</p>\n<p>اگر GIF بڑی رہنی چاہیے تو سوچیں کہ کیا GIF درست فارمیٹ ہے۔ MP4 شکل میں مختصر ویڈیو اسی اینیمیشن سے کہیں چھوٹی ہوتی ہے، اور زیادہ تر پلیٹفارم اسے ویسے ہی چلاتے ہیں۔</p>\n<h2 id=\"transparency-in-gifs\">GIF میں شفافیت</h2>\n<p>GIF شفافیت سپورٹ کرتے ہیں، مگر صرف واحد شفاف رنگ کے طور پر، ہموار الفا چینل کے طور پر نہیں۔ پکسل یا تو مکمل شفاف ہوتا ہے یا مکمل مبہم، اس لیے نرم کنارے سخت ہو جاتے ہیں۔</p>\n<p>GIF میکر PNG فریموں سے شفاف پس منظر محفوظ رکھتا ہے جب آؤٹ پٹ اس کے لیے سیٹ ہو۔ شفافیت والا لوگو یا اسٹیکر اپنا دیکھنے والا علاقہ رکھتا ہے۔</p>\n<p>نرم کناروں کو احتیاط چاہیے ہوتی ہے۔ ڈراپ شیڈو یا پنکھ والے کنارے والا لوگو ہالہ دکھائے گا جب شفافیت واحد رنگ تک کم ہو، کیونکہ نیم شفاف پکسل کو ٹھوس یا شفاف بننا ہوتا ہے۔</p>\n<p>شفاف GIF کو ہلکے اور تاریک دونوں پس منظر پر ٹیسٹ کریں۔ سفید پر پوشیدہ ہالہ سیاہ پر واضح ہو سکتا ہے، اور الٹا۔ اگر ہالہ ظاہر ہو تو تصویر کو فلیٹ کریں۔</p>\n<h2 id=\"common-mistakes\">عام غلطیاں</h2>\n<p>سب سے عام غلطی بہت سے فریم ہیں۔ پچاس فریم والی GIF بھیس میں ویڈیو ہے، اور یہ بھاری، سست، اور بورنگ ہو گی۔ فریم فہرست کو ضروری تک کاٹیں۔</p>\n<p>دوسری غلطی ہر فریم کے لیے یکساں تاخیر ہے۔ دسویں سیکنڈ دکھایا گیا عنوان سلائیڈ پڑھا نہیں جا سکتا، اور دسویں سیکنڈ دکھایا گیا حتمی فریم غائب ہو جاتا ہے۔ اہم فریموں کو لمبی تاخیر دیں۔</p>\n<p>تیسری غلطی بہت بڑا آؤٹ پٹ سائز ہے۔ چیٹ پیغام کے لیے 1000 پکسل چوڑی ایکسپورٹ شدہ GIF 500 پکسل ورژن سے چار گنا پکسل ہے، اور چیٹ ایپ اسے ویسے بھی نیچے سکیل کرے گی۔</p>\n<p>آخر میں، بہت سے لوگ تصویر GIF پر پیلیٹ کوالٹی کو نظر انداز کرتے ہیں۔ کم پیلیٹ سیٹنگ تصویر کو پوسٹر جیسی گڑبڑ میں بدل دیتی ہے، بینڈ والے آسمان اور دھبے والی جلد کے ساتھ۔ تصاویر کے لیے کوالٹی بڑھائیں۔</p>\n<h2 id=\"quick-reference\">فوری حوالہ: GIF میکر چیک لسٹ</h2>\n<p>میل کھانے والے ابعاد والے پانچ سے پندرہ فریم چنیں، انہیں کہانی ترتیب سے لگائیں، اور تقریباً پانچ فریم فی سیکنڈ کی بنیادی تاخیر سیٹ کریں۔ عنوان اور حتمی فریم کو لمبی تاخیر دیں۔</p>\n<p>منزل کے لیے آؤٹ پٹ چوڑائی سیٹ کریں، جب ہر تفصیل اہمیت رکھے تو Contain اور جب فریم صاف بھرنا ہو تو Cover استعمال کریں، اور تصاویر کے لیے پیلیٹ کوالٹی بڑھائیں۔</p>\n<p>مرحلہ بہ مرحلہ بنانے کے لیے <a href=\"/ur/blog/tasaveer-se-gif-kaise-banayein/\">How to Make a GIF from Images</a> پڑھیں، اور سائز تبادلے کی تفصیل کے لیے <a href=\"/ur/blog/gif-frame-rate-file-size/\">GIF Frame Rate and File Size: Smooth vs Small</a> پڑھیں۔ اپنی GIF <a href=\"/ur/gif-maker/\">GIF maker</a> سے بنائیں۔</p>\n";

